#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_FILE_SIZE 1024 * 1024 * 10 // 10MB
#define MAX_FILES 1000
#define KEY_SIZE 32
#define IV_SIZE 16

// Function to generate a random key and IV
void generate_key_iv(unsigned char *key, unsigned char *iv) {
    FILE *fp = fopen("/dev/urandom", "r");
    if (fp == NULL) {
        printf("Error opening /dev/urandom\n");
        exit(1);
    }

    fread(key, 1, KEY_SIZE, fp);
    fread(iv, 1, IV_SIZE, fp);
    fclose(fp);
}

// Function to encrypt a file using AES-256-CBC
void encrypt_file(const char *filename, unsigned char *key, unsigned char *iv) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }

    struct stat sb;
    fstat(fd, &sb);
    if (sb.st_size > MAX_FILE_SIZE) {
        printf("File %s is too large\n", filename);
        exit(1);
    }

    unsigned char *buf = malloc(sb.st_size);
    read(fd, buf, sb.st_size);
    close(fd);

    AES_KEY aes_key;
    AES_set_encrypt_key(key, 256, &aes_key);
    AES_cbc_encrypt(buf, buf, sb.st_size, &aes_key, iv, AES_ENCRYPT);

    fd = open(filename, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error opening file %s for writing\n", filename);
        exit(1);
    }

    write(fd, buf, sb.st_size);
    close(fd);
